def everyone_in_madrid(apps, schema_editor):
    """Every business so far is in Madrid. Only the city is added: nothing else changes.

    The neighbourhood needs the official boundaries, which need the network, so
    `manage.py setup_geography` assigns it afterwards.
    """
    City = apps.get_model('core', 'City')
    madrid, _ = City.objects.get_or_create(ine_code=MADRID['ine_code'], defaults=MADRID)
    apps.get_model('core', 'Business').objects.filter(city__isnull=True).update(city=madrid)
    apps.get_model('core', 'PlaceSnapshot').objects.filter(city__isnull=True).update(city=madrid)


